func SettlePayout(ctx context.Context, payoutID string) error {
    key := "lock:payout:" + payoutID
    token := uuid.NewString()

    ok, err := rdb.SetNX(ctx, key, token, 30*time.Second).Result()
    if err != nil {
        return fmt.Errorf("acquire %s: %w", key, err)
    }
    if !ok {
        return ErrLockHeld
    }
    defer rdb.Eval(ctx, releaseCAS, []string{key}, token)

    // p99 of this call is 45s -- longer than the 30s lock TTL.
    return psp.Transfer(ctx, payoutID)
}
